package at.hausgarten.service;

import android.content.Context;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.io.IOException;
import java.time.Instant;
import java.util.*;

/** Durable, epoch-bound browser review in the existing database, separate from ordinary checkpoints. */
final class RestoredBrowserCheckpoint {
    private static final String ACTIVE="restored_browser_checkpoint_active";
    private final Context context;private final PixelLocalStore store;
    RestoredBrowserCheckpoint(Context context,PixelLocalStore store){this.context=context;this.store=store;}
    static void install(SQLiteDatabase database,String request,JSONObject manifest,JSONObject browser,JSONObject identity)throws Exception {
        JSONObject source=RestoredBrowserReviewRules.validate(browser);String key="restored_browser_checkpoint:"+PixelMcpWriteTools.hash(request),raw=DatabaseBackupSnapshot.ownerValue(database,key,"");
        if(!raw.isEmpty()){JSONObject old=new JSONObject(raw);if(!PixelMcpWriteTools.hash(source).equals(old.optString("source_sha256"))||!identity.getString("installationId").equals(old.optString("installationId"))||!identity.getString("restoreEpoch").equals(old.optString("restoreEpoch")))throw held();}
        else put(database,key,new JSONObject().put("formatVersion",1).put("phase","REVIEW_REQUIRED").put("activation_request",request).put("backup_id",manifest.getString("backupId")).put("captured_at",manifest.getString("capturedAt")).put("installationId",identity.getString("installationId")).put("restoreEpoch",identity.getString("restoreEpoch")).put("source_sha256",PixelMcpWriteTools.hash(source)).put("source_browser",source).put("created_at",Instant.now().toString()).toString());
        put(database,ACTIVE,key);put(database,"restored_browser_checkpoint_requires_explicit_review","true");
    }
    boolean available(){return !store.ownerValue(ACTIVE,"").isEmpty();}
    boolean pending()throws Exception {JSONObject record=read();return record!=null&&!record.getString("phase").equals("REVIEWED");}
    void assertCheckpointAllowed()throws Exception {if(pending())throw held();}
    void preserveDevice(JSONObject browser)throws Exception {
        JSONObject checked=RestoredBrowserReviewRules.validate(browser);SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{JSONObject record=read();if(record==null||record.has("device_browser")){db.setTransactionSuccessful();return;}record.put("device_browser",checked).put("device_sha256",PixelMcpWriteTools.hash(checked)).put("device_captured_at",Instant.now().toString());save(record);db.setTransactionSuccessful();}finally{db.endTransaction();}
    }
    void reopen()throws Exception {read(); /* Opening a review never revokes a completed decision. */}
    JSONObject status(boolean includeDrafts)throws Exception {
        JSONObject record=read();if(record==null)return new JSONObject().put("available",false).put("review_pending",false);JSONObject out=new JSONObject().put("available",true).put("review_pending",!record.getString("phase").equals("REVIEWED")).put("media_review_pending",record.optBoolean("media_deferred")).put("phase",record.getString("phase")).put("record_hash",PixelMcpWriteTools.hash(record)).put("captured_at",record.getString("captured_at")).put("device_captured",record.has("device_browser")).put("device_captured_at",record.optString("device_captured_at"));
        if(includeDrafts&&record.has("device_browser")){out.put("candidates",RestoredBrowserReviewRules.candidates(record.getJSONObject("source_browser"),"backup"));JSONArray device=RestoredBrowserReviewRules.candidates(record.getJSONObject("device_browser"),"device");for(int i=0;i<device.length();i++)out.getJSONArray("candidates").put(device.get(i));out.put("other_browser_values_preserved",record.getJSONObject("source_browser").getJSONObject("storage").length()+record.getJSONObject("device_browser").getJSONObject("storage").length()-out.getJSONArray("candidates").length());try{JSONObject media=new BrowserMediaRepository(context,store).reviewCandidates();out.put("media_candidates",media.getJSONArray("candidates")).put("media_record_hash",media.getString("record_hash")).put("media_review_required",media.getBoolean("required")).put("media_mirror_complete",media.getBoolean("mirror_complete"));}catch(Exception optional){out.put("media_candidates",new JSONArray()).put("media_review_required",true).put("media_mirror_complete",false).put("media_error_code","BROWSER_MEDIA_REVIEW_REQUIRED");}if(record.has("selection"))out.put("selection",record.getJSONObject("selection"));}return out;
    }
    JSONObject choose(JSONObject args)throws Exception {
        requireRequest(args);if(!Boolean.TRUE.equals(args.opt("confirmed")))throw held();JSONObject identity=new BackupDeviceGuard(context).current();String fingerprint=PixelMcpWriteTools.hash(new JSONObject().put("args",args).put("identity",identity)),receipt="restored_browser_selection:"+PixelMcpWriteTools.hash(args.getString("request_id"));SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{
            String prior=store.ownerValue(receipt,"");if(!prior.isEmpty()){JSONObject saved=new JSONObject(prior),current=read();if(!fingerprint.equals(saved.getString("fingerprint"))||current==null||!current.has("selection")||!PixelMcpWriteTools.hash(current.getJSONObject("selection")).equals(PixelMcpWriteTools.hash(saved.getJSONObject("result"))))throw held();db.setTransactionSuccessful();return saved.getJSONObject("result").put("replayed",true);}
            JSONObject record=read();if(record==null||!record.has("device_browser")||!record.optString("phase").equals("REVIEW_REQUIRED")||!PixelMcpWriteTools.hash(record).equals(args.getString("expected_record_hash")))throw held();
            JSONObject selected=RestoredBrowserReviewRules.selection(record.getJSONObject("source_browser"),record.getJSONObject("device_browser"),args.getJSONArray("selected")),result=new JSONObject().put("projection_version",3).put("request_id",args.getString("request_id")).put("selected",new JSONArray(args.getJSONArray("selected").toString())).put("selected_storage",selected).put("clear_storage",record.getJSONObject("device_browser").getJSONObject("storage")).put("selection_hash",PixelMcpWriteTools.hash(selected)).put("replayed",false);
            if(Boolean.TRUE.equals(args.opt("defer_media"))){if(args.getJSONArray("selected_media").length()!=0)throw held();result.put("media_deferred",true);}else{BrowserMediaRepository media=new BrowserMediaRepository(context,store);JSONObject mediaStatus=media.reviewCandidates();if(mediaStatus.getBoolean("required")){if(!mediaStatus.getBoolean("mirror_complete"))throw held();JSONArray picked=args.getJSONArray("selected_media");String expectedMedia=args.getString("expected_media_hash");JSONObject prepared=media.prepareRestoreSelection(args.getString("request_id"),expectedMedia,picked);result.put("media_selection_hash",prepared.getString("selection_hash")).put("expected_media_hash",expectedMedia).put("selected_media",new JSONArray(picked.toString()));}else if(args.optJSONArray("selected_media")!=null&&args.getJSONArray("selected_media").length()!=0)throw held();}

            record.put("phase","SELECTION_PENDING").put("selection",result);save(record);store.putOwnerValue(receipt,new JSONObject().put("fingerprint",fingerprint).put("result",result).toString());db.setTransactionSuccessful();return result;
        }finally{db.endTransaction();}
    }
    JSONObject complete(JSONObject args)throws Exception {
        requireRequest(args);SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{JSONObject record=read(),selection=record==null?null:record.optJSONObject("selection");if(selection==null||!selection.getString("request_id").equals(args.getString("request_id"))||!selection.getString("selection_hash").equals(args.getString("selection_hash"))||!Boolean.TRUE.equals(args.opt("readback_confirmed")))throw held();
            if(record.getString("phase").equals("REVIEWED")){db.setTransactionSuccessful();return new JSONObject().put("reviewed",true).put("replayed",true);}
            if(!record.getString("phase").equals("SELECTION_PENDING"))throw held();if(selection.has("media_selection_hash"))new BrowserMediaRepository(context,store).activateSelection(selection.getString("request_id"),selection.getString("media_selection_hash"));if(selection.optBoolean("media_deferred"))try{new BrowserMediaRepository(context,store).deferRestoreReview(selection.getString("request_id"));}catch(Exception optional){/* Business review completes; corrupt optional media remains isolated. */}record.put("media_deferred",selection.optBoolean("media_deferred")).put("phase","REVIEWED").put("reviewed_at",Instant.now().toString());save(record);store.putOwnerValue("restored_browser_checkpoint_requires_explicit_review","false");db.setTransactionSuccessful();return new JSONObject().put("reviewed",true).put("replayed",false);
        }finally{db.endTransaction();}
    }
    JSONObject completeMedia(JSONObject args)throws Exception {
        requireRequest(args);if(!Boolean.TRUE.equals(args.opt("confirmed")))throw held();SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{
            JSONObject record=read();if(record==null||!record.getString("phase").equals("REVIEWED"))throw held();BrowserMediaRepository media=new BrowserMediaRepository(context,store);
            JSONObject prepared=media.prepareRestoreSelection(args.getString("request_id"),args.getString("expected_media_hash"),args.getJSONArray("selected_media"));media.activateSelection(args.getString("request_id"),prepared.getString("selection_hash"));record.put("media_deferred",false);save(record);db.setTransactionSuccessful();return new JSONObject().put("media_reviewed",true);
        }finally{db.endTransaction();}
    }
    private JSONObject read()throws Exception {
        String key=store.ownerValue(ACTIVE,"");if(key.isEmpty())return null;if(!key.matches("restored_browser_checkpoint:[0-9a-f]{64}"))throw held();JSONObject record=new JSONObject(store.ownerValue(key,"{}")),identity=new BackupDeviceGuard(context).current();if(record.optInt("formatVersion")!=1||!Arrays.asList("REVIEW_REQUIRED","SELECTION_PENDING","REVIEWED").contains(record.optString("phase"))||!identity.getString("installationId").equals(record.optString("installationId"))||!identity.getString("restoreEpoch").equals(record.optString("restoreEpoch"))||!record.getString("source_sha256").equals(PixelMcpWriteTools.hash(RestoredBrowserReviewRules.validate(record.getJSONObject("source_browser")))))throw held();if(record.has("device_browser")&&!record.getString("device_sha256").equals(PixelMcpWriteTools.hash(RestoredBrowserReviewRules.validate(record.getJSONObject("device_browser")))))throw held();if(record.getString("phase").equals("REVIEW_REQUIRED")){if(record.has("selection"))throw held();}else{if(!record.has("device_browser")||record.optJSONObject("selection")==null)throw held();RestoredBrowserReviewRules.validateSelection(record.getJSONObject("source_browser"),record.getJSONObject("device_browser"),record.getJSONObject("selection"));JSONObject selection=record.getJSONObject("selection");if(record.getString("phase").equals("SELECTION_PENDING")&&selection.has("media_selection_hash"))new BrowserMediaRepository(context,store).verifyPreparedRestoreSelection(selection.getString("request_id"),selection.getString("expected_media_hash"),selection.getJSONArray("selected_media"),selection.getString("media_selection_hash"));}return record;
    }
    private void save(JSONObject record)throws Exception {String key=store.ownerValue(ACTIVE,"");store.putOwnerValue(key,record.toString());if(record.has("device_browser"))store.putOwnerValue("restored_browser_device_archive:"+PixelMcpWriteTools.hash(new JSONObject().put("active",key).put("device_sha256",record.getString("device_sha256"))),record.getJSONObject("device_browser").toString());}
    private static void requireRequest(JSONObject args)throws Exception {if(!args.optString("request_id").matches("[A-Za-z0-9_-]{8,200}"))throw held();}
    private static IOException held(){return new IOException("BACKUP_BROWSER_RESTORE_REVIEW_REQUIRED");}
    private static void put(SQLiteDatabase db,String key,String value){android.content.ContentValues row=new android.content.ContentValues();row.put("key",key);row.put("value",value);db.insertWithOnConflict("owner_state",null,row,SQLiteDatabase.CONFLICT_REPLACE);}
}
